export function renderRoomGraphEditorHtml(initial) {
    const data = JSON.stringify(initial).replaceAll("<", "\\u003c");
    return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Room connector graph</title><style>
*{box-sizing:border-box}body{margin:0;font:14px system-ui;background:#eef2f6;color:#17202a}.app{display:grid;grid-template-columns:400px 1fr;min-height:100vh}.panel{padding:18px;background:#fff;overflow:auto}.canvas{padding:18px}.row{display:grid;grid-template-columns:1fr 1fr;gap:8px}.card{border:1px solid #cbd5e1;padding:9px;margin:8px 0}label{display:block;font-weight:650;margin-top:7px}input,select,button{width:100%;padding:8px;margin-top:3px}.primary{background:#2563eb;color:#fff;border:0}.toolbar{display:flex;gap:6px}.toolbar button{width:auto}svg{width:100%;height:72vh;background:#fff;border:1px solid #cbd5e1}.room-box{fill:#eff6ff;stroke:#1d4ed8;stroke-width:2}.room-node text{text-anchor:middle;pointer-events:none}.port{stroke:#fff;stroke-width:2;cursor:crosshair}.door{fill:#16a34a}.open-passage{fill:#f59e0b}.window{fill:#38bdf8}.wall-link{fill:#64748b}.link{stroke:#334155;stroke-width:3}.preferred{stroke-dasharray:8 5}.drag{cursor:grab}.selected{filter:drop-shadow(0 0 5px #f59e0b)}.danger{color:#b42318}.muted{color:#64748b}@media(max-width:850px){.app{grid-template-columns:1fr}svg{height:55vh}}</style></head><body><div class="app"><section class="panel"><h1>Rooms</h1><label>Home name<input id="home"></label><div class="row"><label>Name<input id="name"></label><label>Type<select id="type"></select></label></div><label>Size<select id="size"><option>small</option><option selected>medium</option><option>large</option></select></label><button id="add-room" class="primary">Add room</button><div id="rooms"></div><h2>Add room connector</h2><label>Room<select id="c-room"></select></label><div class="row"><label>Wall<select id="side"><option>top</option><option>right</option><option>bottom</option><option>left</option></select></label><label>Type<select id="c-type"><option>door</option><option>open-passage</option><option>window</option><option>wall-link</option></select></label></div><label>Position<input id="position" type="range" min="0.1" max="0.9" step="0.1" value="0.5"></label><button id="add-port" class="primary">Add connector</button><h2>Link connectors</h2><div class="row"><label>A<select id="a"></select></label><label>B<select id="b"></select></label></div><label>Importance<select id="importance"><option>required</option><option>preferred</option></select></label><button id="add-link" class="primary">Link connectors</button><div id="links"></div><div class="toolbar"><button id="download">Download JSON</button><button id="load">Load JSON</button><input id="file" type="file" hidden></div><p id="status"></p></section><main class="canvas"><h1>Adjacency graph</h1><p>Drag rooms continuously. Connector markers show wall, type, and position. Select two markers to link them.</p><svg id="graph" viewBox="0 0 900 620"></svg></main></div><script>
let model=${data};const pos={},selected=[];const q=id=>document.getElementById(id),types=['living-room','dining-room','kitchen','bedroom','bathroom','office','hall','laundry','garage','other'];q('type').innerHTML=types.map(x=>'<option>'+x+'</option>').join('');q('home').value=model.name;
const slug=s=>s.toLowerCase().trim().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'item',esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');const rooms=()=>model.rooms,room=id=>rooms().find(r=>r.id===id),ports=()=>rooms().flatMap(r=>r.connectors||[]),port=id=>ports().find(c=>c.id===id);const dims=r=>r.sizeCategory==='large'?{w:170,h:120}:r.sizeCategory==='small'?{w:110,h:80}:{w:140,h:100};
function point(c){const r=room(c.roomId),p=pos[r.id],d=dims(r),t=+c.position;if(c.side==='top')return{x:p.x-d.w/2+t*d.w,y:p.y-d.h/2};if(c.side==='bottom')return{x:p.x-d.w/2+t*d.w,y:p.y+d.h/2};if(c.side==='left')return{x:p.x-d.w/2,y:p.y-d.h/2+t*d.h};return{x:p.x+d.w/2,y:p.y-d.h/2+t*d.h}}
function ensure(){const n=rooms().length;rooms().forEach((r,i)=>{if(!pos[r.id]){const a=-Math.PI/2+i*2*Math.PI/Math.max(n,1);pos[r.id]={x:450+Math.cos(a)*210,y:310+Math.sin(a)*210}}})}
function selects(){const ro=rooms().map(r=>'<option value="'+r.id+'">'+esc(r.name)+'</option>').join('');q('c-room').innerHTML=ro;const used=new Set(model.relationships.flatMap(l=>[l.connectorA,l.connectorB]));const po=ports().filter(c=>!used.has(c.id)&&c.type!=='window').map(c=>'<option value="'+c.id+'">'+esc(room(c.roomId).name+' · '+c.side+' · '+c.type)+'</option>').join('');q('a').innerHTML=po;q('b').innerHTML=po}
function panel(){selects();q('rooms').innerHTML=rooms().map(r=>'<div class="card"><b>'+esc(r.name)+'</b> · '+r.sizeCategory+'<br>'+r.connectors.map(c=>esc(c.side+' '+c.type+' @ '+c.position)+' <button data-rm-port="'+c.id+'">×</button>').join('<br>')+'</div>').join('');q('links').innerHTML=model.relationships.map(l=>'<div class="card">'+esc(room(port(l.connectorA).roomId).name+' '+port(l.connectorA).side)+' ↔ '+esc(room(port(l.connectorB).roomId).name+' '+port(l.connectorB).side)+' <button data-rm-link="'+l.id+'">Remove</button></div>').join('');q('status').textContent=rooms().length+' rooms · '+ports().length+' connectors · '+model.relationships.length+' links'}
function graph(){ensure();const svg=q('graph');svg.innerHTML=model.relationships.map(l=>{const a=point(port(l.connectorA)),b=point(port(l.connectorB));return '<line id="e-'+l.id+'" class="link '+l.importance+'" x1="'+a.x+'" y1="'+a.y+'" x2="'+b.x+'" y2="'+b.y+'"/>'}).join('')+rooms().map(r=>{const p=pos[r.id],d=dims(r);return '<g class="room-node drag" data-room="'+r.id+'" transform="translate('+(p.x-d.w/2)+','+(p.y-d.h/2)+')"><rect class="room-box" width="'+d.w+'" height="'+d.h+'"/><text x="'+d.w/2+'" y="'+d.h/2+'">'+esc(r.name)+'</text></g>'}).join('')+ports().map(c=>{const p=point(c);return '<circle class="port '+c.type+(selected.includes(c.id)?' selected':'')+'" data-port="'+c.id+'" cx="'+p.x+'" cy="'+p.y+'" r="8"><title>'+esc(room(c.roomId).name+' · '+c.side+' · '+c.type)+'</title></circle>'}).join('');bindDrag()}
function render(){model.name=q('home').value||'My Home';panel();graph()}
q('add-room').onclick=()=>{const name=q('name').value.trim();if(!name)return;let id=slug(name),i=2;while(room(id))id=slug(name)+'-'+i++;model.rooms.push({id,name,type:q('type').value,sizeCategory:q('size').value,connectors:[]});q('name').value='';render()};q('add-port').onclick=()=>{const roomId=q('c-room').value;if(!roomId)return;const side=q('side').value,type=q('c-type').value,position=+q('position').value;let id=roomId+'-'+side+'-'+type,i=2;while(port(id))id=roomId+'-'+side+'-'+type+'-'+i++;room(roomId).connectors.push({id,roomId,side,type,position});render()};
function link(a,b){if(!a||!b||a===b)return alert('Choose two connectors.');const x=port(a),y=port(b);if(x.roomId===y.roomId)return alert('Choose different rooms.');if(model.relationships.some(l=>[l.connectorA,l.connectorB].includes(a)||[l.connectorA,l.connectorB].includes(b)))return alert('A connector is already linked.');model.relationships.push({id:[a,b].sort().join('--'),connectorA:a,connectorB:b,importance:q('importance').value});selected.length=0;render()}q('add-link').onclick=()=>link(q('a').value,q('b').value);
document.addEventListener('click',e=>{const p=e.target.closest('[data-port]');if(p){if(!selected.includes(p.dataset.port))selected.push(p.dataset.port);if(selected.length===2)link(selected[0],selected[1]);else graph();return}const rp=e.target.closest('[data-rm-port]');if(rp){const id=rp.dataset.rmPort;rooms().forEach(r=>r.connectors=r.connectors.filter(c=>c.id!==id));model.relationships=model.relationships.filter(l=>l.connectorA!==id&&l.connectorB!==id);render()}const rl=e.target.closest('[data-rm-link]');if(rl){model.relationships=model.relationships.filter(l=>l.id!==rl.dataset.rmLink);render()}});q('home').oninput=()=>{model.name=q('home').value;panel()};
q('download').onclick=()=>{const b=new Blob([JSON.stringify(model,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=slug(model.name)+'-connectors.json';a.click();URL.revokeObjectURL(a.href)};q('load').onclick=()=>q('file').click();q('file').onchange=async e=>{const f=e.target.files[0];if(!f)return;model=JSON.parse(await f.text());Object.keys(pos).forEach(k=>delete pos[k]);q('home').value=model.name;render()};
function update(id){const r=room(id),p=pos[id],d=dims(r),g=document.querySelector('[data-room="'+CSS.escape(id)+'"]');g.setAttribute('transform','translate('+(p.x-d.w/2)+','+(p.y-d.h/2)+')');r.connectors.forEach(c=>{const v=point(c),el=document.querySelector('[data-port="'+CSS.escape(c.id)+'"]');el.setAttribute('cx',v.x);el.setAttribute('cy',v.y)});model.relationships.forEach(l=>{if(r.connectors.some(c=>c.id===l.connectorA||c.id===l.connectorB)){const a=point(port(l.connectorA)),b=point(port(l.connectorB)),el=q('e-'+l.id);el.setAttribute('x1',a.x);el.setAttribute('y1',a.y);el.setAttribute('x2',b.x);el.setAttribute('y2',b.y)}})}
function bindDrag(){document.querySelectorAll('[data-room]').forEach(g=>{g.onpointerdown=e=>{const id=g.dataset.room,svg=q('graph');g.setPointerCapture(e.pointerId);const move=ev=>{const p=svg.createSVGPoint();p.x=ev.clientX;p.y=ev.clientY;const v=p.matrixTransform(svg.getScreenCTM().inverse());pos[id]={x:Math.max(90,Math.min(810,v.x)),y:Math.max(70,Math.min(550,v.y))};update(id)};g.addEventListener('pointermove',move);g.onpointerup=()=>{g.removeEventListener('pointermove',move);g.releasePointerCapture(e.pointerId)}}})}render();
</script></body></html>`;
}
